INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('go-go-nekketsu-hockey-club-slip-and-slide-madness', 48630, '1992-02-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4i18.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gnq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go-Go! Nekketsu Hockey Club Slip-and-Slide Madness', 'Hey there, this is the Nekketsu High School Paper. Our own Kunio has become famous as a leader. With him we won both the dodge ball and soccer championships. They competed and won at the world stage, it is truly amazing. But did you know, Nekketsu High also has an ice hockey club? Sadly, our team is very weak... We probably won''t even make the playoffs in the next national championship. Perhaps Kunio can lead our ice hockey team to victory as well. With him, would it become a successful team, or still be in the minor leagues? Passionate ice hockey spirit! Good luck everyone!
