INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Blazer', 'Soul Blazer, known in Japan as Soul Blader, is a Super Nintendo Entertainment System action role-playing game developed by Quintet and published by Enix (now Square Enix). Soul Blazer was released on January 31, 1992 in Japan, on November 27, 1992 in North America, and on January 27, 1994 in Europe. Similar to the company''s previous game ActRaiser, the player takes the role of a divine angel, deity or lesser-deity, or avatar, sent by a divinity, called The Master, to destroy monsters and release the captured souls of a world''s inhabitants. Soul Blazer was scored by Yukihide Takekawa.' FROM games WHERE igdb_id = 11616 ON CONFLICT (game_id, language_code) DO NOTHING;
