INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Musya: The Classic Japanese Tale of Horror', 'Action platformer developed by Jorudan and published by Datam Polystar for the Super Nintendo Entertainment System. The game was translated into English by Seta U.S.A.. Musya was released in Japan on April 21, 1992 and in North America in December 1992. The name Musya is romanized by the English translators in the Kunrei-shiki style (Musya) instead of the Hepburn romanization style (Musha).' FROM games WHERE igdb_id = 36740 ON CONFLICT (game_id, language_code) DO NOTHING;
