INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-simpsons-bart-s-nightmare', 2833, '1992-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4av9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8lz.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Bart''s Nightmare', 'Bart has to stay up late and write a paper for class tomorrow. For once, he is determined to get a good mark. However, very quickly, he falls asleep. Nightmare after nightmare haunt his subconscious, and it is up to you to get over each one, so that Bart will eventually wake up. From such dreams as being in an episode of Itchy & Scratchy to swimming through his own bloodstream, this platformer offers a nice challenge through its many diverse levels.' FROM games WHERE igdb_id = 2833 ON CONFLICT (game_id, language_code) DO NOTHING;
