INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones and the Fate of Atlantis', 'A point-and-click adventure game by LucasArts originally released in 1992. Almost a year later, it was reissued on CD-ROM as an enhanced "talkie" edition with full voice acting and digitized sound effects. In 2009, this version was also released as an unlockable extra of the Wii action game Indiana Jones and the Staff of Kings, and as a digitally distributed Steam title. The seventh game to use the script language SCUMM, Fate of Atlantis has the player explore environments and interact with objects and characters by using commands constructed with predetermined verbs. It features three unique paths to select, influencing story development, gameplay and puzzles.' FROM games WHERE igdb_id = 184 ON CONFLICT (game_id, language_code) DO NOTHING;
