INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('romancing-saga', 11311, '1992-01-28', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2x50.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm621.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romancing SaGa', 'A thousand years ago, Saruin was imprisoned. Now the barriers that contain him are weakening, and his foreboding shadow threatens to swallow the world of Mardias once again. Who will rid the world of Saruin''s scourge? A mysterious minstrel appears and guides the group to adventure, at times shielding them from adversity. Occasionally, the minstrel forces grave choices upon them, which change their world and twist the plots they encounter. Romancing SaGa reclaims the renowned features of the series and boasts all new elements enhancing gameplay, bringing the player even deeper into the story. The free-roaming scenario system gives gamers a choice of eight intriguing playable characters, each with their own unique adventures and individual goals. Depending on the character and actions chosen, the plot and the subsequent events differentiate dramatically. This free-roaming scenario system promises the ultimate in open-ended adventure.' FROM games WHERE igdb_id = 11311 ON CONFLICT (game_id, language_code) DO NOTHING;
