INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar: The Silver Star', 'Welcome to the world of Lunar, where reigns the magic and dragons still live. Join Alex, a young adventurer and his companions Luna, Ramus and Nall, to save the land of the Magic Emperor Ghaleon tyranny. Explore dungeons, fight terrifying monsters, and collects local information of where to go along to the explosive confrontation with Ghaleon own.' FROM games WHERE igdb_id = 5334 ON CONFLICT (game_id, language_code) DO NOTHING;
