INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bio-Hazard Battle', 'During the first global biowar, a powerful retrovirus filled the planet Avaron with new and deadly forms of life. Only a few survivors remain in O.P. Odysseus, an orbiting platform circling Avaron. Hundreds of years after the biowar, conditions on Avaron are still hostile but livable.' FROM games WHERE igdb_id = 4517 ON CONFLICT (game_id, language_code) DO NOTHING;
