INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splatterhouse 2', 'Three months have gone by since the events of the first game. The Terror Mask, which has reformed after breaking at the climax of the first game, appears to Rick and repeatedly tempts him to "go back to the house", telling him that Jennifer "doesn''t have to die". It closes by telling Rick "You need me.". Rick succeeds in rescuing Jennifer, and the House sinks into the bottom of the river.' FROM games WHERE igdb_id = 46248 ON CONFLICT (game_id, language_code) DO NOTHING;
