INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Paint', 'Mario Paint is an educational game that allows anyone to create simple pictures, paint over black and white pictures, or free draw their own using the specially developed SNES Mouse. The player can also create their own piece of music using a selection of notes and themes, create greeting cards and animations, or play a game of "Gnat Attack", where they use the mouse to control a swatter to swat flies.' FROM games WHERE igdb_id = 8203 ON CONFLICT (game_id, language_code) DO NOTHING;
