INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man 5', 'In the fifth chapter of the original Mega Man series, the battle is closer to home as Mega Man fights to save the world from further destruction. Gain the advantage by picking up items and successfully defeating bosses to gain their weapons as your own. Get ready for intense action-platforming in 13 stages before taking up battle against Protoman!' FROM games WHERE igdb_id = 1718 ON CONFLICT (game_id, language_code) DO NOTHING;
