INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castles II: Siege & Conquest', 'In this game of medieval diplomacy, treachery & power. To win you must survive. To survive you must scout the surrounding territories, defeat the local militias, subjugate the land with castles, feed the people, forge diplomatic alliances, appease the church and unite the land under your iron fist.' FROM games WHERE igdb_id = 51576 ON CONFLICT (game_id, language_code) DO NOTHING;
