INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Racing', 'This game was the first game released for the Sega Model 1 arcade platform, and also the first to use the name "Virtua" in its title (something which would be followed by numerous Sega arcade games, including Virtua Fighter, Virtua Cop and Virtua Tennis. It is considered a milestone in 3D graphics and the racing genre, and acts as a foundation for most modern racing games.' FROM games WHERE igdb_id = 8172 ON CONFLICT (game_id, language_code) DO NOTHING;
