INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mitsume ga Tooru', 'Mitsume ga Tōru is a 2D action platformer released in 1992. It was never released outside Japan. It contains 5 levels with a boss fight at the end of each level. The main character´s weapons are the third eye that shoots bullets, boomerangs or lasers and a spear (the Red Condor) that he can materialize from the air. The game is based on the manga and anime of the same name.' FROM games WHERE igdb_id = 48666 ON CONFLICT (game_id, language_code) DO NOTHING;
