INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Franken', 'Being the first version that was released, the Game Boy version of the game uses a password-based saving system to save the player''s progress. The game consisted of seven floors where various items and parts of Bitsy (Franky''s girlfriend) were hidden. Keys and special items were needed to access additional areas to find more body parts and equipment required to resurrect Bitsy.' FROM games WHERE igdb_id = 48949 ON CONFLICT (game_id, language_code) DO NOTHING;
