INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undercover Cops', 'Undercover Cops is an arcade-style beat ''em up video game developed and published by Irem, originally for the arcades in 1992. It is Irem''s first attempt in the modern beat ''em up genre that was founded by Data East’s Kung-Fu Master. Players control "city sweepers", a police agent-like group who fight crime by taking down thugs in New York City in the year 2043.' FROM games WHERE igdb_id = 10455 ON CONFLICT (game_id, language_code) DO NOTHING;
