INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moto-roader-mc', 79389, '1992-12-18', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3o1i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gw4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moto Roader MC', 'Moto Roader MC is a racing game by NCS and is the third episode of the Moto Roader series. Up to five players can race each other on twenty five tracks (five courses of five tracks each) as they vie for the first place. Unlike other games of the series, each track is constructed of a single static screen and is reminiscent of the arcade classic Super Sprint. Each race is made out of eight laps where anything goes! Cars are invincible and can fire an unlimited amount of rockets and bombs which, consequently, leads the gameplay more towards speed and attack. All the racing tracks display a showcase of exquisite themes - from classic "City" and "Nature" scapes to more elaborate designs such as the fantasy "Marchen" or the unique "Special" courses. Road hazards also spice up the game and make each play session unique - from classic pits, speed boosters to shortcuts and disorienting teleporters.' FROM games WHERE igdb_id = 79389 ON CONFLICT (game_id, language_code) DO NOTHING;
