INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contra Force', 'Contra Force is an action shooting game released by Konami for the Nintendo Entertainment System in 1992 in North America. It is a spinoff of the Contra series, being the third game in the series released for the NES following the original Contra and Super Contra, although the game''s plot and setting are unrelated to previous entries, as the villains in the game are human terrorists instead of an alien menace' FROM games WHERE igdb_id = 24978 ON CONFLICT (game_id, language_code) DO NOTHING;
