INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest V: Tenkuu no Hanayome', 'Dragon Quest V: Tenkuu no Hanayome is a role-playing video game and the fifth installment in the Dragon Quest video game series, second of the Zenithian Trilogy. Originally developed by Chunsoft and published by Enix Corporation, Dragon Quest V was the first title in the series to be released for the Super Famicom video game console in Japan in September 1992. Dragon Quest V was the first game in the series to not be released outside Japan due to programming issues at the time.' FROM games WHERE igdb_id = 205595 ON CONFLICT (game_id, language_code) DO NOTHING;
