INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chester Cheetah: Too Cool to Fool', 'The game''s hero is the Frito-Lay mascot, Chester the Cheetah. Chester leaves peacefully in a zoo with other animals, until the big brute Mean Eugene steals his beloved motor scooter. What''s worse, without knowing how to handle the scooter, Mean Eugene broke it to pieces and threw them away. Now it''s up to Cheetah to travel across the zoo and to retrieve parts of his scooter.' FROM games WHERE igdb_id = 46255 ON CONFLICT (game_id, language_code) DO NOTHING;
