INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Carnival ''92: Recca', 'Conceived as an entry for a game development competition, this game would later be published by Naxat Soft in 1992. This frenetic shoot-''em-up taxes the Famicom system and the player''s reflexes with huge quantities of enemies while maintaining smooth, fast gameplay! In addition to a single player campaign, there are also score attack and time attack modes available.' FROM games WHERE igdb_id = 48642 ON CONFLICT (game_id, language_code) DO NOTHING;
