INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('art-of-fighting', 4514, '1992-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22y4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30rc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art of Fighting', 'This fighting game began the story of the Sakazaki family and Robert Garcia. Yuri Sakazaki has been abducted by Mr. Big to punish her father, Takuma, and her brother, Ryo. To rescue her, Ryo and Robert must take on numerous enemies around South Town, eventually reaching the mysterious Mr. Karate. The passion of the game’s creators is evident in the unique game play elements introduced. These include an energy gauge that is depleted every time a fighter uses a special maneuver, Desperation Attacks that are usable only when a fighter’s health is low, and camera zooming that adjusts on the fly as fighters move around the stage. All these features ensure that players use strategy and tactics, rather than simply mash buttons. Adding to the mix are little touches such as characters showing cuts when they are injured and voice-over samples during cut scenes. Can you perfect the art of fighting and save Yuri?' FROM games WHERE igdb_id = 4514 ON CONFLICT (game_id, language_code) DO NOTHING;
