INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-trophy-soccer', 4390, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5p0z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scieux.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Trophy Soccer', 'The world''s most popular sport has never been so exciting. Enjoy all of the action of international competition; passing, dribbling, and tackling your way to hard-fought victory. Use complete directional control to master corner kicks, penalty shots, throw-ins, and more. An on-screen referee is on hand to enforce international rules in either Arcade or Simulation play styles. You determine the nationality, strategy, and even the uniform color for your team, and then get ready for a gigantic tournament that will put your country''s character to the test. Adjust the match lengths to meet your attention span, choose your difficulty level, and prepare to enjoy the most realistic soccer animations and game play ever.' FROM games WHERE igdb_id = 4390 ON CONFLICT (game_id, language_code) DO NOTHING;
