INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Kart', 'Super Mario Kart is a racing game for the Super Nintendo Entertainment System and the first game of the Mario Kart series, as well as the game that sets precedents to the fictional kart racing genre. Part of this game is heavily based on Super Mario World in terms of graphics and overall theme. Using Mode 7 scaling, the first true kart game on the SNES has you collecting coins to boost your speed while using shells and bananas to stop others on the track.' FROM games WHERE igdb_id = 2332 ON CONFLICT (game_id, language_code) DO NOTHING;
