INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Fantasy Zone', 'Super Fantasy Zone is an entry in the Fantasy Zone series of games, and was initially released in 1992 for the Sega Mega Drive. Unlike previous outings, Super Fantasy Zone was handled entirely by Sunsoft (under license from Sega), who had previously brought Fantasy Zone and Fantasy Zone II to the Nintendo Famicom.
