INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lotus-iii-the-ultimate-challenge', 12672, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jmt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8kmi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lotus III: The Ultimate Challenge', 'The third game in the series combined the gameplay aspects of its predecessors, allowing players to choose between racing opponents of Lotus Turbo Challenge or the arcade-like time trials of Lotus 2. The two-player option was retained and the music selection feature returns (Patrick Phelan''s soundtrack to Lotus III spawned many modern remixes). Lotus III also added a third car - a concept Lotus M200 automobile - and allowed the player to choose which one to race with. The game recycled most of the graphics from Lotus 2, but added a number of new sceneries.' FROM games WHERE igdb_id = 12672 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 12672 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
