INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Olympic Gold: Barcelona ''92', 'Each computer athlete has a fictional name and nationality (choosing from UK, France, Germany, Italy, Spain, USA, Japan and the Unified Team, everyone with its own anthem snippet) and actual strengths and weaknesses: J. Balen, for instance, is a frequent 100 m and 110 m hurdles record breaker but only an average hammer thrower. Also, each computer controlled player seems better in a particular event depending on his country: Germans usually take the top spots in archery, Italians on swimming, Russians on pole vault, Americans on sprinting and so on.' FROM games WHERE igdb_id = 46266 ON CONFLICT (game_id, language_code) DO NOTHING;
