INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zool: Ninja of the Nth Dimension', 'Zool is a fast-paced side-scrolling platformer. The protagonist can run, jump, climb walls, and shoot enemies. Power-ups for Zool are scattered across the levels. These include life-spending hearts, smart bombs, shields, more powerful jump-skill and a twin Zool. This "twin" makes imitates the original''s motions a few seconds after he performs them.' FROM games WHERE igdb_id = 2547 ON CONFLICT (game_id, language_code) DO NOTHING;
