INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlaZeon: The Bio-Cyborg Challenge', 'The player is set in control of The Garland TFF-01, a sub-standard space fighter ship that is only armed with a semi-auto or rapid fire laser gun known as the Beam Vulcan and the Tranquilander. Some enemy units can be captured and used in play; certain enemy robots, when shot by the player''s Tranquilander, will morph into an outline of themselves. The player can then fly into the outline, and take on the form of the enemy robot, taking control of its weapons, agilities and special attacks.' FROM games WHERE igdb_id = 42625 ON CONFLICT (game_id, language_code) DO NOTHING;
