INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ecco the Dolphin', 'Life was an adventure for Ecco, the young dolphin. The ocean seemed endless with rolling breakers to race through! At high speed Ecco could burst through the waves leaping through the air – almost flying! Until one day, all of that changed. A freak whirlpool of air and water tore the life from Ecco’s home leaving Ecco all alone. Now he must fight to stay alive, while traversing the vast ocean in search of clues that will help him save his family and return them to the bay.' FROM games WHERE igdb_id = 5378 ON CONFLICT (game_id, language_code) DO NOTHING;
