INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix', 'Asterix is a horizontal-scrolling beat''em up arcade game released in 1992 by Konami. It is based on the French comic series Asterix and Obelix. The player fights as either Asterix the Gaul or his best friend, Obelix, as they take on the ''might'' of the oppressive Roman Empire. Asterix includes a variety of humorous fighting moves, which are demonstrated in the game''s attract mode. The artwork and feel of Asterix remains true to its French source material, and the game''s many humorous touches (such as the way defeated Legionnaires crawl away) will be instantly familiar to fans of the comic-book and cartoon series. Bonus levels - such as the chariot race that awaits at the end of the first level - introduce different gameplay elements to provide a break from the fighting.' FROM games WHERE igdb_id = 128475 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 128475 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
