INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles IV: Turtles in Time', 'Teenage Mutant Ninja Turtles IV: Turtles in Time, developed by Konami, is a side-scrolling beat ’em up for up to two players. It is the fourth game in the series, following Teenage Mutant Ninja Turtles III: The Manhattan Project on the Nintendo Entertainment System. Originally released as an arcade game, it was later ported to the Super Nintendo Entertainment System in 1992.' FROM games WHERE igdb_id = 14697 ON CONFLICT (game_id, language_code) DO NOTHING;
