INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Putt-Putt Joins the Parade', 'Putt-Putt Joins the Parade is not only the first game in the Putt-Putt series, but the first game ever released by Humongous Entertainment. This "Junior Adventure" aimed at young children has fairly low stakes — you help Putt-Putt the car join a local parade — but was a stepping stone for the developer''s later, somewhat more sophisticated titles.' FROM games WHERE igdb_id = 3733 ON CONFLICT (game_id, language_code) DO NOTHING;
