INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Control II', 'Star Control II, the sequel to the original Star Control, is a space adventure game that features role-playing elements alongside a 2D space ship melee combat system. The player assumes the role of The Captain of a single starship wandering a detailed environment of solar systems, gradually gathering information and resources in order to defeat a mysterious and implacable enemy.' FROM games WHERE igdb_id = 1046 ON CONFLICT (game_id, language_code) DO NOTHING;
