INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brawl Brothers', 'Released in 1992 for the Super Nintendo Entertainment System, Brawl Brothers is a side-scrolling beat ''em up game by Jaleco, serving as the sequel to Rival Turf! and preceding The Peace Keepers in 1993. Set in Bayside City, where people are vanishing amidst rumors of sinister human cloning experiments, the game follows Rick and Doug, who are driven by personal stakes when three friends from their martial arts gym are abducted.' FROM games WHERE igdb_id = 42639 ON CONFLICT (game_id, language_code) DO NOTHING;
