INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pools of Darkness', 'For ten years your glorious band has fought Evil wherever it has threatened the Realms. Lord Bane has suffered many defeats at your hands and new peace washes over the land. Now your path comes full circle - back to the thriving city of Phlan.
