INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psycho Dream', 'Sayaka Kaori has fallen into a coma. However, she can be reached by a machine that can people into dreams. Dreams are incredibly surreal places, and are often very dangerous. Only experts from The National Public Safety Commission, also known as Diamond Dogs, are authorized to enter. It''s up to Ryo and Maria, two of the best Diamond Dog officers, to save Sayaka and wake her from her coma.' FROM games WHERE igdb_id = 42420 ON CONFLICT (game_id, language_code) DO NOTHING;
