INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Viewpoint', 'One or two players (in hot-seat or cooperative mode) control a spaceship equipped with a laser cannon which can be charged (by holding the shooting button down) for a stronger blast. Besides the main weapon, three special weapons are available: a wall of fire which wipes the screen up in a wave, a nova-like blast and a circle of spherical-green homing missiles.' FROM games WHERE igdb_id = 20707 ON CONFLICT (game_id, language_code) DO NOTHING;
