INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire ''n Ice', 'The aim of the game involves players extinguishing all fires in a level in order to proceed. They do this by creating and melting ice (in a Lode Runner style) or kicking ice onto the fires. This game also has a level editor (which may expose some bugs that substantially affect the game mechanics).' FROM games WHERE igdb_id = 48671 ON CONFLICT (game_id, language_code) DO NOTHING;
