INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soldier Blade', 'Vertical sci-fi shoot ‘em up from the Hudson stable. Soldier Blade sticks to the tried and tested formula of Hudson’s previous games in the ''series'', while throwing in some extra graphical effects. This time, the power up system involves collecting coloured pods - you can have three pods in stock at any one time, and the colour of the ''active'' pod determines your weapon style. You also have the choice of ejecting a pod at any time, which results in a weapon-specific super attack.' FROM games WHERE igdb_id = 15841 ON CONFLICT (game_id, language_code) DO NOTHING;
