INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien 3', 'Alien³ was released after the Alien 3 film. After success on the Super Nintendo and Genesis platforms, the game was built and ported to other systems, including the Commodore 64 and Game Gear. The game is set on the world of the film, Fury 161, but the gameplay has more in common with the film Aliens, throwing wave after wave of enemies at the player.' FROM games WHERE igdb_id = 8908 ON CONFLICT (game_id, language_code) DO NOTHING;
