INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XF5700 Mantis Experimental Fighter', 'Out of nowhere, an army of insect-like creatures from a distant world, using technologically advanced space weapons, ambushed and devastated Earth. In this colorful space shooter from the early days of FMV, it’s up to you to fend off the Sirian race in the cutting edge XF5700 Mantis Fighter!' FROM games WHERE igdb_id = 93316 ON CONFLICT (game_id, language_code) DO NOTHING;
