INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Nicklaus Golf', 'The biggest name in golf brings you the most realistic and feature-backed golf simulation ever! Play on two of Jack Nicklaus'' favorite courses or design an unlimited number of your own. One to four players can compete on beginner and expert levels. You control every detail of the action. The password feature even lets your take a break. If you''re ready to play against the best, JACK NICKLAUS GOLF is your game!' FROM games WHERE igdb_id = 49040 ON CONFLICT (game_id, language_code) DO NOTHING;
