INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Aquatic Games: Starring James Pond and the Aquabats', 'James Pond is on a break from baddie bashing to compete in the Aquatic Games in Basselona. Play with Pond''s fishy friends as they vie for the coveted Goldfish medal in 10 wet and wacky events. Practice all you want and qualify for the Official Games, or play with up to four friends in your own maritime match. Your porpoise - uh... purpose - is to be the first across the finish line, but you''ll be hooked long before then!' FROM games WHERE igdb_id = 4554 ON CONFLICT (game_id, language_code) DO NOTHING;
