INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cacoma Knight in Bizyland', 'Cacoma Knight is a hybrid of action and puzzle elements. Each level is a single screen. The first image that the player sees is a landscape, for example, a forest or a town. The image will then fade into a "corrupt" version of the landscape, for example, the trees become rotten and buildings become ruined. Each screen has a "Qualify" target that shows how much of the screen must be cleared before the game continues to the next level.' FROM games WHERE igdb_id = 42734 ON CONFLICT (game_id, language_code) DO NOTHING;
