INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'George Foreman''s KO Boxing', 'You''re "Big George" Foreman - the people''s champion - and you''ve got an appetite for big action that only KO boxing can satisfy. It''s a full menu of hard-hitting, real-ring action! Take on a roster of heavyweight contenders as you go for the World Championship. Rock your opponents with stinging left-right combos and pound your way to the title with a spectacular "Big George" Super Punch, while the computer tracks the action. George Foreman''s KO Boxing puts the power of the greatest knockout artist in your hands!' FROM games WHERE igdb_id = 48164 ON CONFLICT (game_id, language_code) DO NOTHING;
