INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apidya', 'The game is a side-on scrolling shoot-em-up. The story revolves around Ikuro, whose wife Yuri has been poisoned by Hexaae, an evil lord of black magic. Ikuro uses magic to transform into a deadly bee and vows to find an antidote for Yuri and wreak revenge on Hexaae.' FROM games WHERE igdb_id = 11906 ON CONFLICT (game_id, language_code) DO NOTHING;
