INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Dreams', 'DICE’s first game was built by five friends from the Amiga demo group The Silents in their spare time. What started out as a demo idea soon became a full-fledged pinball simulation published by 21st Century Entertainment with the Amiga as the primary platform. Pinball Dreams captivated gamers and quickly became a cult hit.' FROM games WHERE igdb_id = 3024 ON CONFLICT (game_id, language_code) DO NOTHING;
