INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Home Alone 2: Lost in New York', 'Kevin ends up in New York City Alone. The "Wet Bandits" are in New York City too. Harry and Marv tried to rob Kevin''s house last Christmas. But Kevin''s excellent traps foiled their plans. Now they''re out for revenge. And Kevin''s got plenty of hilarious plans to stop them.' FROM games WHERE igdb_id = 14502 ON CONFLICT (game_id, language_code) DO NOTHING;
