INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Cricket', 'International Cricket is one of the few NES titles released exclusively in Australia. It is the brother game of Aussie Rules Footy. The player can choose from eight teams; Australia, England, India, New Zealand, Pakistan, South Africa, Sri Lanka, and West Indies. Additionally there is a hidden team called The Beam Team, where each of the developers'' portraits is represented by Sonic the Hedgehog. From the menu there are different types of play modes the player can choose from.' FROM games WHERE igdb_id = 65196 ON CONFLICT (game_id, language_code) DO NOTHING;
