INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Darkwing Duck', 'Darkwing Duck is a platformer video game based on the Disney television series, Darkwing Duck. The game was developed by Capcom for the Nintendo Entertainment System in 1992 and was ported to the Game Boy in 1993. The Game Boy version is essentially a slightly stripped-down version of the game. The game was re-released in 2017 as part of the Disney Afternoon Collection.' FROM games WHERE igdb_id = 8452 ON CONFLICT (game_id, language_code) DO NOTHING;
