INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grind Stormer', '"Grind Stormer" is a 1993 vertically scrolling shooter arcade video game originally developed and published by Toaplan in Japan and North America. It is considered to be the spiritual successor to Slap Fight. Based around a video game within a video game concept, players assume the role of a young secret agent assigned by the government taking control of the NA-00 space fighter craft in an attempt to defeat the titular virtual reality simulator, rescue the abducted players who lost against it and unveil its true purpose.' FROM games WHERE igdb_id = 4420 ON CONFLICT (game_id, language_code) DO NOTHING;
