INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superman', 'Superman (known in Europe as Superman: The Man of Steel) is a video game released by Sunsoft for the Mega Drive/Genesis in 1992. It is based on the DC Comics character of the same name. It is a traditional single-player side-scrolling arcade game where the player controls Superman through various levels in an effort to defeat the evil supervillain named Brainiac. Other super villains, as bosses, include The Prankster, Metallo and Mister Mxyzptlk.' FROM games WHERE igdb_id = 81522 ON CONFLICT (game_id, language_code) DO NOTHING;
