INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Rash II', 'Road Rashing isn''t just a sport. It''s an attitude! Road Rash II is the ultimate 2-player racing game with a radically unique split-screen for distinguishing between racers. Cruising cross-country was never this hairy! Spectacular new body-torquing wipe outs! More obstacles to crash into than ever before. Terrorize your opponents on 5 new tracks, each with 5 different levels. Swing a steel chain for some real heavy metal damage! 15 brand new, lightning-fast cycles, including nitro-equipped Super-Bikes!' FROM games WHERE igdb_id = 4429 ON CONFLICT (game_id, language_code) DO NOTHING;
