INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom and Jerry: The Movie', 'Oooooh, that mouse! If there''s one thing Tom can''t stand, it''s a rascally rodent named Jerry, and if that mouse isn''t careful, Tom is going to nab him. But Jerry is pretty tricky. So muster up all your feline courage, Tom, ''cause there''s a dangerous little mouse in the house!' FROM games WHERE igdb_id = 8043 ON CONFLICT (game_id, language_code) DO NOTHING;
