INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warriors of Fate', 'Warriors of Fate is a beat''em up with nine stages. Each contains large mobs including spearman, archers, strongmen, bomb-wielding opponents, and at least one boss. Using two buttons, Attack and Jump, the characters all have standard moves typical of Capcom side-scrollers of the day.
