INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baseball Stars 2', 'Baseball Stars 2 is the sequel to the very successful Baseball Stars game released for Nintendo in the late 1980s. It was released by SNK for Arcade, as well as the Nintendo Entertainment System. Players can create leagues of up to 125 games (6 teams playing each other 25 times) and view statistics such as League Standings, Average, Home Runs, Runs Batted In, Earned Run Average, Wins and Saves. Players can fire players and upgrade them using the same 15-point system introduced in the original Baseball Stars.' FROM games WHERE igdb_id = 9942 ON CONFLICT (game_id, language_code) DO NOTHING;
