INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaeru-no-tame-ni-kane-wa-naru', 49078, '1992-09-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dk2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar20h0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaeru no Tame ni Kane wa Naru', 'In a land far away, the two princes—Richard (of the Custard Kingdom) and the game''s main protagonist (prince of the Sablé Kingdom)—have shared a friendly rivalry since they were small children. They often compete, although it usually ends in a tie or close win. In Fencing however, Prince Richard is always the victor. One day a messenger arrives from a small neighboring kingdom, warning the princes that the evil King Delarin has invaded the Mille-Feuille Kingdom and captured the beautiful princess Tiramisu. In yet another boastful attempt to best the Sablé Prince, Richard grabs a boat and rushes towards the kingdom. The Sablé Prince is left trying to catch up. While on his journey, he and Richard (and many others) are transformed into frogs in an attempt to reveal the true happenings in this kingdom.
